import test from'node:test';import assert from'node:assert/strict';import fs from'node:fs';
import {decodeMarket,decodeBook,bookRequest}from'../protobuf.mjs';import {marketBytes,bookBytes,NOW}from'./fixtures.mjs';import {DEMO_MARKET,demoSnapshot}from'../demo.mjs';import {quoteSpot}from'../quote.mjs';
const read=name=>JSON.parse(fs.readFileSync(new URL(name,import.meta.url),'utf8'));
test('independently generated Python protobuf messages match JS encode and decode',()=>{const v=read('./golden-protobuf.json');assert.equal(Buffer.from(marketBytes()).toString('hex'),v.marketHex);assert.equal(Buffer.from(bookBytes()).toString('hex'),v.bookHex);assert.equal(Buffer.from(bookRequest(DEMO_MARKET).slice(5)).toString('hex'),v.requestHex);assert.equal(decodeMarket(Buffer.from(v.marketHex,'hex')).marketId,DEMO_MARKET);assert.equal(decodeBook(Buffer.from(v.bookHex,'hex')).sequence,'9007199254740993');});
test('512 seeded cases agree with Fraction and exhaustive per-level lot oracle',()=>{const vectors=read('./arithmetic-vectors.json');for(const [index,v]of vectors.cases.entries()){const s=demoSnapshot('injective',NOW);s.market.lotAtomic=v.lotAtomic;s.market.takerFeeRate=v.rate;s.market.minNotionalQuote={numerator:'0',denominator:'1'};s[v.side==='sell-base'?'bids':'asks']=v.levels;const q=quoteSpot(s,{side:v.side,inputAtomic:v.inputAtomic},{now:NOW});for(const [k,value]of Object.entries(v.expected))assert.equal(q[k],value,`case ${index} ${k}`);assert.ok(BigInt(q.consumedInputAtomic)<=BigInt(v.inputAtomic));}});
